def parse(s):
    root = None
    stack = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c == '[':
            lst = []
            if stack:
                stack[-1].append(lst)
            else:
                root = lst
            stack.append(lst)
            i += 1
        elif c == ']':
            stack.pop()
            i += 1
        elif c == ',' or c.isspace():
